// Advisory model changes check order only. All rejects have exact final-state witnesses.
const TAIL:usize=96;
type PointTriple=((U256,U256),(U256,U256),(U256,U256));
struct Packet{keys:Vec<u8>,next:usize,batches:Vec<Vec<PointTriple>>}
impl Packet{
 fn ensure(&mut self,batch:usize,curve:&FastCurveC)->bool{while self.batches.len()<=batch{let mut pts=Vec::with_capacity(64);while pts.len()<64&&self.next<NUM_TESTS{let count=(64-pts.len()).min(NUM_TESTS-self.next);let mut scalars=Vec::with_capacity(count*2);for i in self.next..self.next+count{let off=i*64;scalars.push(U256::from_le_slice(&self.keys[off..off+32]));scalars.push(U256::from_le_slice(&self.keys[off+32..off+64]));}self.next+=count;for(t,o,e)in curve.points_with_sums(&scalars){if t.0!=o.0&&!(t.0.is_zero()&&t.1.is_zero())&&!(o.0.is_zero()&&o.1.is_zero()){pts.push((t,o,e));}}}if pts.is_empty(){return false;}self.batches.push(pts);}true}
}
fn nonce_tail(tail:&[Op],nonce:u64)->Vec<Op>{assert!(nonce<1<<48);let mut t=tail.to_vec();for b in 0..48{t[2*b].q_target=QubitId((nonce>>b)&1);t[2*b+1].q_target=QubitId((nonce>>b)&1);}t}
fn tail_nonce_of(tail:&[Op])->u64{(0..48).map(|b|(tail[2*b].q_target.0&1)<<b).sum()}
fn exact_batch(p:&Compact,packets:&[Packet],indices:[usize;8],active:[bool;8],regs:&[Vec<QubitOrBit>],nq:usize,nb:usize,rng:&[u64])->[&'static str;8]{
 let mut q=vec![0u64;nq*8];let mut b=vec![0u64;nb*8];let mut phase=[0u64;8];let mut stack=vec![0u64;4096*8];let mut used=0usize;
 for j in 0..8{if !active[j]{continue;}for(lane,(t,o,_))in packets[j].batches[indices[j]].iter().enumerate(){for(reg,value)in regs[..4].iter().zip([t.0,t.1,o.0,o.1]){for(i,wire)in reg.iter().enumerate(){let v=(value.bit(i)as u64)<<lane;match wire{QubitOrBit::Qubit(id)=>q[id.0 as usize*8+j]|=v,QubitOrBit::Bit(id)=>b[id.0 as usize*8+j]|=v}}}}}
 assert_eq!(unsafe{(exact_backend().run)(p.ops.as_ptr(),p.ops.len(),q.as_mut_ptr(),b.as_mut_ptr(),phase.as_mut_ptr(),rng.as_ptr(),p.rng_count,stack.as_mut_ptr(),4096,&mut used)},0);assert_eq!(used,p.rng_count);
 let mut result=["inactive";8];for j in 0..8{if !active[j]{continue;}let pts=&packets[j].batches[indices[j]];let mask=if pts.len()==64{u64::MAX}else{(1u64<<pts.len())-1};let mut classical=false;
 for(lane,(_,_,expected))in pts.iter().enumerate(){for(reg,value)in regs[..2].iter().zip([expected.0,expected.1]){for(i,wire)in reg.iter().enumerate(){let raw=match wire{QubitOrBit::Qubit(id)=>q[id.0 as usize*8+j],QubitOrBit::Bit(id)=>b[id.0 as usize*8+j]};classical|=((raw>>lane)&1)!=(value.bit(i)as u64);}}}
 for reg in regs{for wire in reg{if let QubitOrBit::Qubit(id)=wire{q[id.0 as usize*8+j]=0;}}}let ancilla=(0..nq).any(|i|q[i*8+j]&mask!=0);result[j]=if classical{"classical"}else if phase[j]&mask!=0{"phase"}else if ancilla{"ancilla"}else{"pass"};}result
}

struct PreparedPacket{packet:Packet,ctx:Arc<Shake8>,lane:usize,nonce:u64,selected:usize,hit:bool,prepsecs:f64}
fn prepare8(base:&Shake8,hash:&Shake256,tail:&[Op],nonces:[u64;8],valid:[bool;8],curve:&FastCurveC,_model:&())->Vec<PreparedPacket>{
 let start=std::time::Instant::now();let mut encoded=Vec::with_capacity(TAIL*49*8);for nonce in nonces{for op in nonce_tail(tail,nonce){encoded.extend_from_slice(&record49(&op));}}let mut ctx=base.copy();ctx.different(&encoded,TAIL*49);ctx.finalize();let keys=ctx.squeeze(NUM_TESTS*64);
 for j in 0..8{let mut h=hash.clone();h.update(&encoded[j*TAIL*49..(j+1)*TAIL*49]);let mut check=[0u8;64];XofReader::read(&mut h.finalize_xof(),&mut check);assert_eq!(&check,&keys[j*NUM_TESTS*64..j*NUM_TESTS*64+64]);}let ctx=Arc::new(ctx);let mut result=Vec::new();
 for j in 0..8{if !valid[j]{continue;}let mut packet=Packet{keys:keys[j*NUM_TESTS*64..(j+1)*NUM_TESTS*64].to_vec(),next:0,batches:Vec::new()};let selected=0;let hit=false;assert!(packet.ensure(0,curve));result.push(PreparedPacket{packet,ctx:ctx.clone(),lane:j,nonce:nonces[j],selected,hit,prepsecs:0.0});}let elapsed=start.elapsed().as_secs_f64();for p in&mut result{p.prepsecs=elapsed;}result
}
fn confirm_bucket(prefix:&Compact,mut prepared:Vec<PreparedPacket>,regs:&[Vec<QubitOrBit>],nq:usize,nb:usize,curve:&FastCurveC)->Vec<serde_json::Value>{
 let start=std::time::Instant::now();assert!(!prepared.is_empty()&&prepared.len()<=8);let len=prepared.len();let contexts=std::array::from_fn(|j|prepared[j.min(len-1)].ctx.0 as *const c_void);let lanes=std::array::from_fn(|j|prepared[j.min(len-1)].lane as u32);let mut ctx=Shake8::combine(contexts,lanes);
 // Independent lane routing check before any batch-offset consumption.
 let mixed=ctx.copy().squeeze(64);for j in 0..len{let original=prepared[j].ctx.copy().squeeze(64);let lane=prepared[j].lane;assert_eq!(&mixed[j*64..(j+1)*64],&original[lane*64..(lane+1)*64],"regrouped nonce/lane route mismatch");}
 let indices=std::array::from_fn(|j|if j<len{prepared[j].selected}else{0});let valid=std::array::from_fn(|j|j<len);let nonces:Vec<_>=prepared.iter().map(|p|p.nonce).collect();let hits:Vec<_>=prepared.iter().map(|p|p.hit).collect();let prepsecs:Vec<_>=prepared.iter().map(|p|p.prepsecs).collect();let mut packets:Vec<_>=prepared.drain(..).map(|p|p.packet).collect();while packets.len()<8{packets.push(Packet{keys:Vec::new(),next:NUM_TESTS,batches:Vec::new()});}
 let mut selected=ctx.copy();let rngstart=std::time::Instant::now();let rng=selected.select(indices.map(|i|i*prefix.rng_count),prefix.rng_count);let rngsecs=rngstart.elapsed().as_secs_f64();let exactstart=std::time::Instant::now();let mut active=valid;for j in 0..8{active[j]&=packets[j].ensure(indices[j],curve);}let result=exact_batch(prefix,&packets,indices,active,regs,nq,nb,&rng);let exactsecs=exactstart.elapsed().as_secs_f64();drop(rng);let mut kinds=["pass";8];let mut witness=[None;8];let mut batches=[0;8];let mut remaining=valid;
 for j in 0..8{if active[j]{batches[j]+=1;if result[j]!="pass"{kinds[j]=result[j];witness[j]=Some(indices[j]);remaining[j]=false;}}else{remaining[j]=false;}}
 let mut i=0;while remaining.iter().any(|x|*x){let mut check=[false;8];for j in 0..8{if !remaining[j]{continue;}if !packets[j].ensure(i,curve){remaining[j]=false;continue;}check[j]=i!=indices[j];}let rng=ctx.words(prefix.rng_count);if check.iter().any(|x|*x){let results=exact_batch(prefix,&packets,[i;8],check,regs,nq,nb,&rng);for j in 0..8{if check[j]{batches[j]+=1;if results[j]!="pass"{kinds[j]=results[j];witness[j]=Some(i);remaining[j]=false;}}}}i+=1;}
 (0..len).map(|j|serde_json::json!({"nonce":nonces[j],"pass":witness[j].is_none(),"kind":kinds[j],"batches_run":batches[j],"exact_witness_batch":witness[j],"advisory_batch":indices[j],"advisory_hit":hits[j],"prepared_batches":packets[j].batches.len(),"bucket_size":len,"advisory_backend":"avx512_rails8","selected_rng_group_secs":rngsecs,"selected_exact_group_secs":exactsecs,"bucket_max_batch":*indices.iter().max().unwrap(),"preparation_group_secs":prepsecs[j],"confirmation_group_secs":start.elapsed().as_secs_f64(),"rejection_policy":"exact_full_state_only"})).collect()
}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),8,"OPS FIRST COUNT THREADS OUT MODEL_SOURCE LOOKAHEAD");let ops=load_ops(&a[1]).unwrap();let n=ops.len();let tail=ops[n-TAIL..].to_vec();for pair in tail.chunks_exact(2){assert_eq!(pair[0],pair[1]);assert_eq!(pair[0].kind,OperationType::X);assert_eq!(pair[0].c_condition.0,u64::MAX);}let own=tail_nonce_of(&tail);let(nq,nb,_,regs)=analyze_ops(ops.iter());let first=a[2].parse::<u64>().unwrap();let count=a[3].parse::<usize>().unwrap();let threads=a[4].parse::<usize>().unwrap();let lookahead=a[7].parse::<usize>().unwrap();assert!(threads>0&&threads<=16&&lookahead>0&&lookahead<=1024);
 let mut base=Shake8::new();let mut hash=Shake256::default();for bytes in [b"quantum_ecc-fiat-shamir-v2".as_slice(),&(n as u64).to_le_bytes()]{base.same(bytes);hash.update(bytes);}let mut encoded=Vec::with_capacity(49*32768);for op in &ops[..n-TAIL]{encoded.extend_from_slice(&record49(op));if encoded.len()>=49*32768{base.same(&encoded);hash.update(&encoded);encoded.clear();}}if !encoded.is_empty(){base.same(&encoded);hash.update(&encoded);}let p=Compact::compile(&ops[..n-TAIL]);let curve=FastCurveC::new(20);if std::env::var_os("QUALIFY").is_some(){qualify(&ops,&p,&base,&hash,&tail,&curve,&regs,nq as usize,nb as usize);return;}let model=();let best=std::sync::atomic::AtomicU64::new(u64::MAX);let out=Mutex::new(File::create(&a[5]).unwrap());let started=std::time::Instant::now();let mut total_prep=0.0;let mut total_confirm=0.0;
 for window in (0..count).step_by(lookahead){let stop=(window+lookahead).min(count);if first+window as u64>best.load(Ordering::SeqCst){break;}let next=AtomicUsize::new(window);let prepared=Mutex::new(Vec::new());let t=std::time::Instant::now();std::thread::scope(|scope|{for _ in 0..threads{scope.spawn(||loop{let ix=next.fetch_add(8,Ordering::SeqCst);if ix>=stop{break;}let nonces=std::array::from_fn(|j|first+(ix+j).min(stop-1)as u64);let valid=std::array::from_fn(|j|ix+j<stop);let packets=prepare8(&base,&hash,&tail,nonces,valid,&curve,&model);prepared.lock().unwrap().extend(packets);} );}});total_prep+=t.elapsed().as_secs_f64();let prepared=prepared.into_inner().unwrap();let t=std::time::Instant::now();for result in dense_confirm(prepared,&p,&regs,nq as usize,nb as usize,&curve,threads){if result["pass"]==true{best.fetch_min(result["nonce"].as_u64().unwrap(),Ordering::SeqCst);}writeln!(out.lock().unwrap(),"{result}").unwrap();}total_confirm+=t.elapsed().as_secs_f64();}
 let b=best.load(Ordering::SeqCst);println!("BUCKET_SCREEN_DONE own={own} first={first} count={count} lookahead={lookahead} threads={threads} best={b} wall_seconds={:.6} preparation_seconds={total_prep:.6} confirmation_seconds={total_confirm:.6} exact_confirmation=true",started.elapsed().as_secs_f64());if b!=u64::MAX{let mut rewritten=ops[..n-TAIL].to_vec();rewritten.extend(nonce_tail(&tail,b));let r=run_tests(&rewritten,&regs,nq,nb,fiat_shamir_seed(&rewritten),NUM_TESTS);assert!(r.ok);println!("SELECTED_OFFICIAL_REPLAY nonce={b} ok={} shots={} classical={} phase={} ancilla={}",r.ok,r.n_shots,r.classical_failures,r.phase_garbage_batches,r.ancilla_garbage_batches);}}

fn sha_check(path:&str,expected:&str){let o=std::process::Command::new("sha256sum").arg(path).output().unwrap();assert!(o.status.success());assert_eq!(String::from_utf8(o.stdout).unwrap().split_whitespace().next().unwrap(),expected);}
struct Words{v:Vec<u8>,at:usize}
impl XofReader for Words{fn read(&mut self,out:&mut[u8]){out.copy_from_slice(&self.v[self.at..self.at+out.len()]);self.at+=out.len();}}
fn qualify(ops:&[Op],p:&Compact,base:&Shake8,hash:&Shake256,tail:&[Op],curve:&FastCurveC,regs:&[Vec<QubitOrBit>],nq:usize,nb:usize){
 let mut prep=prepare8(base,hash,tail,[1,2,3,4,5,6,7,8],[true;8],curve,&());
 for x in &mut prep{assert!(x.packet.ensure(140,curve));assert_eq!(x.packet.next,NUM_TESTS);let mut full=ops[..ops.len()-TAIL].to_vec();full.extend(nonce_tail(tail,x.nonce));let mut reader=fiat_shamir_seed(&full);let mut keys=vec![0;NUM_TESTS*64];XofReader::read(&mut reader,&mut keys);assert_eq!(keys,x.packet.keys);let mut expected=[0;64];XofReader::read(&mut reader,&mut expected);let actual=x.ctx.copy().squeeze(64);assert_eq!(&expected,&actual[x.lane*64..(x.lane+1)*64]);}
 let packets:Vec<_>=prep.iter().map(|x|Packet{keys:x.packet.keys.clone(),next:x.packet.next,batches:x.packet.batches.clone()}).collect();
 for batch in [0,70,140]{let mut ctx=prep[0].ctx.copy();let rng=ctx.select([batch*p.rng_count;8],p.rng_count);let mut q=vec![0;nq*8];let mut b=vec![0;nb*8];let mut phase=[0;8];let mut stack=vec![0;4096*8];let mut used=0;
  for j in 0..8{for(lane,(t,o,e))in packets[j].batches[batch].iter().enumerate(){let off=(batch*64+lane)*64;let k1=U256::from_le_slice(&packets[j].keys[off..off+32]);let k2=U256::from_le_slice(&packets[j].keys[off+32..off+64]);let c=secp256k1();let tr=c.mul(c.gx,c.gy,k1);let or=c.mul(c.gx,c.gy,k2);assert_eq!(*t,tr);assert_eq!(*o,or);assert_eq!(*e,c.add(tr.0,tr.1,or.0,or.1));for(reg,value)in regs[..4].iter().zip([t.0,t.1,o.0,o.1]){for(i,w)in reg.iter().enumerate(){let v=(value.bit(i)as u64)<<lane;match w{QubitOrBit::Qubit(id)=>q[id.0 as usize*8+j]|=v,QubitOrBit::Bit(id)=>b[id.0 as usize*8+j]|=v}}}}}
  let q0=q.clone();let b0=b.clone();assert_eq!(unsafe{(exact_backend().run)(p.ops.as_ptr(),p.ops.len(),q.as_mut_ptr(),b.as_mut_ptr(),phase.as_mut_ptr(),rng.as_ptr(),p.rng_count,stack.as_mut_ptr(),4096,&mut used)},0);assert_eq!(used,p.rng_count);
  for j in 0..8{let mut reader=Words{v:(0..p.rng_count).flat_map(|i|rng[i*8+j].to_le_bytes()).collect(),at:0};let mut sim=Simulator::new(nq,nb,&mut reader);for i in 0..nq{sim.qubits[i]=q0[i*8+j];}for i in 0..nb{sim.bits[i]=b0[i*8+j];}let mut full=ops[..ops.len()-TAIL].to_vec();full.extend(nonce_tail(tail,j as u64+1));sim.apply_iter(full.iter());assert_eq!(sim.phase,phase[j]);for i in 0..nq{assert_eq!(sim.qubits[i],q[i*8+j]);}for i in 0..nb{assert_eq!(sim.bits[i],b[i*8+j]);}assert_eq!(reader.at,p.rng_count*8);}
  println!("QUALIFIED_FULL_STATE batch={batch} nonces=1..8 scalar_curve=true all_qubits_bits_phase_rng=true");
 }
 for n in [1,2,17,63]{let mask=(1u64<<n)-1;assert_eq!((1u64<<n)&mask,0);assert_ne!((1u64<<(n-1))&mask,0);}
 println!("QUALIFICATION_PASS unique_nonce_controls=8 scalar_full_state_batches=24 partial_masks=1,2,17,63 production_screens=0");
}

// Repacking changes only exact verifier scheduling. Circuit, FS and full-state classifier are unchanged.
fn dense_step(prefix:&Compact,prepared:Vec<PreparedPacket>,batch:usize,regs:&[Vec<QubitOrBit>],nq:usize,nb:usize,curve:&FastCurveC)->(Vec<PreparedPacket>,Vec<serde_json::Value>){
 let len=prepared.len();assert!(len>0&&len<=8);let contexts=std::array::from_fn(|j|prepared[j.min(len-1)].ctx.0 as *const c_void);let lanes=std::array::from_fn(|j|prepared[j.min(len-1)].lane as u32);let mut ctx=Shake8::combine(contexts,lanes);
 let mixed=ctx.copy().squeeze(64);for j in 0..len{let original=prepared[j].ctx.copy().squeeze(64);assert_eq!(&mixed[j*64..(j+1)*64],&original[prepared[j].lane*64..(prepared[j].lane+1)*64],"Every-round dense SHAKE lane routing mismatch");}
 let metadata:Vec<_>=prepared.iter().map(|p|(p.nonce,p.selected,p.hit,p.prepsecs)).collect();let mut packets:Vec<_>=prepared.into_iter().map(|p|p.packet).collect();while packets.len()<8{packets.push(Packet{keys:Vec::new(),next:NUM_TESTS,batches:Vec::new()});}
 let mut active=[false;8];for j in 0..len{active[j]=packets[j].ensure(batch,curve);}let results=if active.iter().any(|x|*x){let rng=ctx.words(prefix.rng_count);exact_batch(prefix,&packets,[batch;8],active,regs,nq,nb,&rng)}else{["inactive";8]};let shared=Arc::new(ctx);let mut survivors=vec![];let mut rows=vec![];
 for(j,packet)in packets.into_iter().take(len).enumerate(){let(nonce,selected,hit,prepsecs)=metadata[j];if active[j]&&results[j]=="pass"{survivors.push(PreparedPacket{packet,ctx:shared.clone(),lane:j,nonce,selected,hit,prepsecs});}else{let pass=!active[j];rows.push(serde_json::json!({"nonce":nonce,"pass":pass,"kind":if pass{"pass"}else{results[j]},"batches_run":if pass{batch}else{batch+1},"exact_witness_batch":if pass{None}else{Some(batch)},"prepared_batches":packet.batches.len(),"rejection_policy":"exact_full_state_only","verifier_schedule":"dense_survivor_repacking","actual_rng_words_per_executed_batch":prefix.rng_count}));}}
 (survivors,rows)
}
fn dense_confirm(mut alive:Vec<PreparedPacket>,prefix:&Compact,regs:&[Vec<QubitOrBit>],nq:usize,nb:usize,curve:&FastCurveC,threads:usize)->Vec<serde_json::Value>{
 let mut batch=0;let mut rows=vec![];while !alive.is_empty(){assert!(batch<=NUM_TESTS.div_ceil(64));alive.sort_by_key(|x|x.nonce);let mut iter=alive.into_iter();let mut groups=std::collections::VecDeque::new();loop{let group:Vec<_>=iter.by_ref().take(8).collect();if group.is_empty(){break;}groups.push_back(group);}let queue=Mutex::new(groups);let next=Mutex::new(Vec::new());let finished=Mutex::new(Vec::new());std::thread::scope(|scope|{for _ in 0..threads{let queue=&queue;let next=&next;let finished=&finished;scope.spawn(move||loop{let Some(group)=queue.lock().unwrap().pop_front()else{break};let(survivors,done)=dense_step(prefix,group,batch,regs,nq,nb,curve);next.lock().unwrap().extend(survivors);finished.lock().unwrap().extend(done);});}});rows.extend(finished.into_inner().unwrap());alive=next.into_inner().unwrap();batch+=1;}rows
}
